// topic → text, or null when it isn't a map topic
function topic(name) {
  const t = String(name || '').toLowerCase().replace(/[^a-z]/g, '');
  const key = TOPICS[t] ? t : ALIAS[t];
  return key ? TOPICS[key] : null;
}

module.exports = { TOPICS, LINE, topic, ALIAS };
